#include <stddef.h>

typedef struct Node {
    int value;
    struct Node *next;
} Node;

Node *list_reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}
pub struct Node {
    pub value: i32,
    pub next: Option<Box<Node>>,
}

/// Helper (already implemented): builds a list from a slice.
pub fn from_vec(v: &[i32]) -> Option<Box<Node>> {
    let mut head = None;
    for &x in v.iter().rev() {
        head = Some(Box::new(Node { value: x, next: head }));
    }
    head
}

/// Helper (already implemented): collects list values.
pub fn to_vec(mut cur: &Option<Box<Node>>) -> Vec<i32> {
    let mut out = Vec::new();
    while let Some(n) = cur {
        out.push(n.value);
        cur = &n.next;
    }
    out
}

